DECKS = [("X", "Cross-Book - Linux vs Windows vs Metasploit (Compare & Contrast)", [
("sa","Linux vs Windows: where are local password hashes stored, and what is the domain equivalent?",
 "Linux: /etc/shadow (readable only by root). Windows: the SAM database locally (protected even from SYSTEM's direct access) and ntds.dit on domain controllers for domain accounts. John the Ripper cracks both.",
 "Links Linux 3.3 with Windows 3.6."),
("sa","Linux vs Windows: how do users and groups get identified?",
 "Linux uses numeric UIDs/GIDs (UID 0 = root) from /etc/passwd and /etc/group. Windows uses SIDs (well-known like S-1-5-18 SYSTEM, or domain/local with a RID such as 500 = Administrator).",
 "Links Linux 2.4 with Windows 2.10."),
("sa","Linux vs Windows: how are file permissions expressed?",
 "Linux: rwx for user/group/world, plus SUID/SGID/sticky, immutable attributes and optional ACLs (getfacl/setfacl). Windows: a security descriptor with owner, primary group, DACL (ordered allow/deny ACEs), SACL (auditing) and flags - managed with icacls/Get-Acl, written as SDDL.",
 "Links Linux Ch6 with Windows 5.10."),
("sa","Linux vs Windows: how does a user run something with elevated rights?",
 "Linux: sudo (configured in /etc/sudoers), su, runuser, and Polkit for graphical actions. Windows: UAC elevation of the split admin token (integrity Medium -> High), Run as administrator, runas.",
 "Links Linux 4.3 with Windows 3.6/Ch7."),
("sa","Linux vs Windows: mandatory access control.",
 "Linux: SELinux (contexts user:role:type:level, Booleans) or AppArmor (per-program profiles, enforce/complain). Windows: integrity levels (Low/Medium/High/System) with mandatory 'no write up', which underpins UAC.",
 "Links Linux Ch7 with Windows Ch7."),
("sa","Linux vs Windows: background programs and startup.",
 "Linux: systemd units (systemctl, journalctl, timers) started by PID 1. Windows: services controlled by the Service Control Manager (services.msc, sc, net, PsService, Get-Service), defined under HKLM\\SYSTEM\\CurrentControlSet\\Services. Both are used by admins and attackers for persistence.",
 "Links Linux 5.6 with Windows 8.3."),
("sa","Linux vs Windows: how do you inspect a process deeply?",
 "Linux: ps/pgrep/pidof/pstree/top and /proc/<pid>/ (exe, cmdline, environ, fd). Windows: tasklist, Task Manager, Process Explorer, Get-Process/Get-CimInstance Win32_Process (parent PID, command line), Process Monitor for activity.",
 "Links Linux 5.6 with Windows 7.6."),
("sa","Linux vs Windows: how is login activity recorded?",
 "Linux: utmp/wtmp/btmp (who, w, last, lastb), lastlog (pam_lastlog.so), systemd-logind (loginctl), and auth.log/secure. Windows: Security event log (4624 logon with logon type, 4625 failed), plus query user, psloggedon and WMI - each with limitations.",
 "Links Linux Ch4 with Windows Ch3."),
("sa","Linux vs Windows: how do attackers hide command history?",
 "Linux: unset HISTFILE, HISTSIZE=0, set +o history, delete ~/.bash_history. Windows: cmd history is per session only; PowerShell's PSReadLine ConsoleHost_history.txt can be deleted or disabled (Set-PSReadLineOption -HistorySaveStyle SaveNothing), and Base64 -EncodedCommand hides the content from logs that do capture command lines. Transcripts and script block logging defeat this.",
 "Links Linux 1.7 with Windows Ch1."),
("sa","Linux vs Windows: how do file links differ?",
 "Linux: hard links (same inode, files only, same file system) and symbolic links (paths, anything). Windows: shortcuts (.lnk files), hard links (files), junctions (directories), and symbolic links (admin-created, relative or network targets) - made with mklink.",
 "Links Linux 6.6 with Windows Ch4."),
("sa","Attack chain: put these book topics in Kill Chain order - brute force, msfvenom payload, phishing document, Meterpreter migrate, AV exclusion, handler.",
 "Weaponization: msfvenom payload / phishing document. Delivery: phishing (or brute force SMB/SSH for credential-based access). Exploitation/Installation: payload runs and the handler receives the callback; an admin adds an AV exclusion for persistence. C2: Meterpreter session. Actions on Objectives: migrate, recon, keylogging, credential phishing.",
 "Ties Metasploit Ch1-7 to the Cyber Kill Chain."),
])]
